import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BD%91%E7%BB%9C/NetWork/","title":"NetWork | notes","lang":"zh-CN","frontmatter":{"title":"NetWork","createTime":"2026/04/04 23:28:20","permalink":"/notes/计算机网络/NetWork/","description":"期末考试习题复习 第1章 imgimg （1）数据长度为img （2）数据长度为img 从以上计算结果可得出什么结论？ 发送时延=数据帧长度(bit)/发送速率(bit/s) 传播延时=信道长度(m)/电磁波在信道上的传播速率(m/s) (1)发送时延img 传播时延img (2)发送时延img 传播时延=5ms 若数据长度大而发送速率低， 则会对发送...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"NetWork\\",\\"image\\":[\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281723488.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281724552.png\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281728361.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281729982.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281729167.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281730356.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281731285.png\\",\\"data:image/png;base64,\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281732476.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281733247.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281738196.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281738606.png\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281740930.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281740079.png\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"data:image/png;base64,\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281742190.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281742546.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281746157.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281750710.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281751066.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281753105.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281753012.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281756617.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281756953.png\\"],\\"dateModified\\":\\"2026-07-13T08:30:33.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BD%91%E7%BB%9C/NetWork/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"NetWork"}],["meta",{"property":"og:description","content":"期末考试习题复习 第1章 imgimg （1）数据长度为img （2）数据长度为img 从以上计算结果可得出什么结论？ 发送时延=数据帧长度(bit)/发送速率(bit/s) 传播延时=信道长度(m)/电磁波在信道上的传播速率(m/s) (1)发送时延img 传播时延img (2)发送时延img 传播时延=5ms 若数据长度大而发送速率低， 则会对发送..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"data:image/png;base64,"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-07-13T08:30:33.000Z"}],["meta",{"property":"article:modified_time","content":"2026-07-13T08:30:33.000Z"}]]},"readingTime":{"minutes":22.56,"words":6769},"git":{"createdTime":1775331561000,"updatedTime":1783931433000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":2,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":4,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"659d4c8bf7219f86c6132394a6b9cd1b55d709f8","time":1783931433000,"email":"xiaofei00152@gmail.com","author":"xiaofei","message":"还原缺失笔记"},{"hash":"713f16c4c942da0098958e09585a3be505e3fa26","time":1783500446000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新博客"},{"hash":"3d96373049af8d6d977b7606dba951e30ab134ab","time":1782445843000,"email":"xiaofei00152@gmail.com","author":"731016","message":"文件名修改"},{"hash":"093620ddda30b62e073298fb1dfabced546aeb87","time":1782444023000,"email":"xiaofei00152@gmail.com","author":"731016","message":"笔记更新"},{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/计算机网络/NetWork.md","headers":[],"bulletin":true}`),a={name:`NetWork.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>期末考试习题复习</p><p><strong>第1章</strong></p><blockquote><figure><img src="data:image/png;base64," alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>（1）数据长度为<img src="data:image/png;base64," alt="img" loading="lazy"></p><p>（2）数据长度为<img src="data:image/png;base64," alt="img" loading="lazy"></p><p>从以上计算结果可得出什么结论？</p></blockquote><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>1S=1000ms</span></span>
<span class="line"><span>1ms=1000us</span></span>
<span class="line"><span>1us=1000ns</span></span>
<span class="line"><span>数据链路层以下：1K=1000,1M=10^6,1G=10^9</span></span>
<span class="line"><span>网络层以上：1K=1024=2^10,1M=2^20,1G=2^30</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>发送时延=数据帧长度(bit)/发送速率(bit/s) 传播延时=信道长度(<strong>m</strong>)/电磁波在信道上的传播速率(<strong>m/s</strong>)</p><p>(1)发送时延<img src="data:image/png;base64," alt="img" loading="lazy"></p><p>传播时延<img src="data:image/png;base64," alt="img" loading="lazy"></p><p>(2)发送时延<img src="data:image/png;base64," alt="img" loading="lazy"></p><p>传播时延=5ms</p><p>若数据长度大而发送速率低， 则会对发送时延产生大的影响；数据长度短，发送速率高，会影响传播时延</p><blockquote><p>1-24 试述具有五层协议的网络体系结构的要点，包括各层的主要功能</p></blockquote><p>法定OSI-RM：七层</p><p>事实TCP/IP：四层</p><p>教学：五层</p><p>（1）<strong>应用层</strong>：通过应用进程之间的交互完成特定网络应用</p><p>（2）<strong>运输层</strong>：两个主机中进程之间的通信，提供通用的数据传输服务</p><p>（3）<strong>网络层</strong>：封装分组，完成路由的选择</p><p>（4）<strong>数据链路层</strong>：两个相邻接点之间封装帧，传输帧</p><p>（5）<strong>物理层</strong>：透明传输比特流</p><p>OSI的体系结构</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281723488.png" alt="image-20220428172325404" tabindex="0" loading="lazy"><figcaption>image-20220428172325404</figcaption></figure><p>TCP/IP的体系结构</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281724552.png" alt="image-20220428172338858" tabindex="0" loading="lazy"><figcaption>image-20220428172338858</figcaption></figure><p>五层协议的体系结构</p><table><thead><tr><th>5</th><th>应用层</th></tr></thead><tbody><tr><td>4</td><td>运输层</td></tr><tr><td>3</td><td>网络层</td></tr><tr><td>2</td><td>数据链路层</td></tr><tr><td>1</td><td>物理层</td></tr></tbody></table><blockquote><p>1-29 有一个点对点链路，长度为50km。若数据在此链路上的传播速度为2* <img src="data:image/png;base64," alt="img" loading="lazy"></p></blockquote><figure><img src="data:image/png;base64," alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><figure><img src="data:image/png;base64," alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><figure><img src="data:image/png;base64," alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>1B=8bit 100字节=100*8bit</p><p><strong>第2章</strong></p><blockquote><p>2-05 物理层的接口有哪些方面的特性？各包含些什么内容？</p></blockquote><p>（1）<strong>机械特性</strong>：指明接口所用接线器的形状和尺寸、引脚数目和排列、固定和锁定装置</p><p>（2）<strong>电气特性</strong>：指明在接口电缆的各条线上出现的电压的范围</p><p>（3）<strong>功能特性</strong>：指明某条线上出现的某一电平的电压的意义</p><p>（4）<strong>过程特性</strong>：指明对于不同功能的各种可能事件的出现顺序</p><p><strong>规格化内积</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>使用CDMA的每一个站被指派一个唯一的m bit码片序列。</span></span>
<span class="line"><span>一个站如果要发送比特1，则发送它自己的m bit码片序列</span></span>
<span class="line"><span>若发送比特0，则发送该码片序列的二进制反码</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>2-16 共有四个站进行码分多址CDMA通信。四个站的码片序列为：</p><p>A：（-1 -1 -1 +1 +1 -1 +1 +1）</p><p>B:（-1 -1 +1 -1 +1 +1 +1 -1）</p><p>C:（-1 +1 -1 +1 +1 +1 -1 -1）</p><p>D:（-1 +1 -1 -1 -1 -1 +1 -1）</p><p>现收到这样的码片序列：（-1 +1 -3 +1 -1 -3 +1 +1）。问哪个站发送数据了？发送数据的站发送的是1还是0？</p></blockquote><p>S<em>A=（-1 +1 -3 +1 -1 -3 +1 +1）</em>（-1 -1 -1 +1 +1 -1 +1 +1）/8=（+1 -1 +3 +1 -1 +3 +1 +1）/8=1 A发送1</p><p>S<em>B=（-1 +1 -3 +1 -1 -3 +1 +1）</em>（-1 -1 +1 -1 +1 +1 +1 -1）/8=（+1 -1 -3 -1 -1 -3 +1 -1）/8=-1 B发送0</p><p>S<em>C=（-1 +1 -3 +1 -1 -3 +1 +1）</em>（-1 +1 -1 +1 +1 +1 -1 -1）/8=（+1 +1 +3 +1 -1 -3 -1 -1）/8=0 C无发送</p><p>S<em>D=（-1 +1 -3 +1 -1 -3 +1 +1）</em>（-1 +1 -1 -1 -1 -1 +1 -1）/8=（+1 +1 +3 -1 +1 +3 +1 -1）/8=1 D发送1</p><p><strong>第3章</strong></p><blockquote><p>3-04 数据链路层的三个基本问题（封装成帧、透明传输和差错检测）为什么都必须加以解决？</p></blockquote><p>封装成帧：PDU格式定义</p><p>透明传输：帧定界</p><p>PPP：字节填充/零比特填充</p><p>Ethernet-&gt;通过数学概率的形式规避部分出现定界问题</p><p>差错控制：</p><p>CSMA/CD 协议的要点</p><p>（1）先听后发</p><p>（2）边听边发</p><p>（3）冲突停止</p><p>（4）随机重发</p><p><strong>CRC冗余校验</strong></p><blockquote><p>3-07 要发送的数据为<strong>1101011011</strong>。采用CRC的生成多项式是P(X)=X^4 + X + 1 。试求应添加在数据后面的余数</p><p>要发送的数据在传输过程中最后一个1变成了0，问接收端能否发现？</p><p>若要发送的数据在传输过程中最后两个1都变成了0，问接收端能否发现？</p><p>采用CRC校验后，数据链路层的传输是否就变成了可靠的传输？</p></blockquote><p>P(X)=X^4 + X + 1 --&gt; 10000+10+1=10011</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281728361.png" alt="image-20220428172848311" tabindex="0" loading="lazy"><figcaption>image-20220428172848311</figcaption></figure><p><strong>除数5位，被除数添加4【5-1】个0</strong></p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281729982.png" alt="image-20220428172921939" tabindex="0" loading="lazy"><figcaption>image-20220428172921939</figcaption></figure><p>除法运算得出的余数，就是添加在<strong>数据后面</strong>的<strong>检验序列</strong></p><p>余数不为0，接收端能够发现</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281729167.png" alt="image-20220428172949127" tabindex="0" loading="lazy"><figcaption>image-20220428172949127</figcaption></figure><p>余数不为0，接收端能够发现</p><blockquote><p>3-08 要发送的数据为101110.采用CRC的生成多项式是P(X)=X^3 + 1 。试求应添加在数据后面的余数</p></blockquote><p>1000+1=1001</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281730356.png" alt="image-20220428173048321" tabindex="0" loading="lazy"><figcaption>image-20220428173048321</figcaption></figure><p><strong>除数4位，被除数添加3【4-1】个0</strong></p><blockquote><p>3-20 假定1km长的CSMA/CD网络的数据率为1Gbit/s。设信号在网络上的传播速率为200 000 km/s。</p><p>求能够使用此协议的最短帧长</p></blockquote><p>端到端的传播时延=（1km）/（200 000km/s）=5 µs 争用期2₹（₹是以太网单程端到端的传播时延）</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281731285.png" alt="image-20220428173144257" tabindex="0" loading="lazy"><figcaption>image-20220428173144257</figcaption></figure><p>=L/C<img src="data:image/png;base64," alt="img" loading="lazy"></p><p><strong>帧长单位Mbit/s</strong></p><p>要发送（1Gbit/s）*（10µs）=10000 bit</p><p>最短帧长10000bit，或1250字节</p><blockquote><p>3-33 在图中，以太网交换机有6个接口，分别接到5台主机和一个路由器</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281732476.png" alt="image-20220428173218068" tabindex="0" loading="lazy"><figcaption>image-20220428173218068</figcaption></figure><p>在下面表的&quot;动作&quot;一栏中，表示先后发送了4个帧。假定在开始时，以太网交换机的交换表是空的。</p><p>试把该表中其他的栏目都填写完。</p></blockquote><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281733247.png" alt="image-20220428173334212" tabindex="0" loading="lazy"><figcaption>image-20220428173334212</figcaption></figure><p><strong>第4章</strong></p><blockquote><p>4-05 IP地址分为几类？各如何表示？IP地址的主要特点是什么？</p></blockquote><p>IP地址共分为5类</p><p><strong>全0全1除外</strong></p><p>A类：<strong>1</strong>.0.0.0 ~ <strong>126</strong>.0.0.0</p><p>B类：<strong>128</strong>.0.0.0 ~ <strong>191</strong>.255.255.255</p><p>C类：<strong>192</strong>.0.0.0 ~ <strong>223</strong>.255.255.255</p><p>D类：<strong>224</strong>.0.0.0 ~ <strong>239</strong>.255.255.255</p><p>E类：<strong>240</strong>.0.0.0 ~ <strong>255</strong>.255.255.255</p><p><strong>主要特点</strong></p><p>（1）IP地址是标志一个主机和一条链路的接口</p><p>（2）每个IP地址由网络号和主机号组成</p><p>（3）不同网络号的局域网必须使用路由器互连</p><p>（4）在IP地址中，所有分配到网络号的网络都是平等的</p><blockquote><p>4-17 一个3200位长的TCP报文传到IP层，加上160位的首部后成为数据报。</p><p>下面的互联网由两个局域网通过路由器连接起来，但第二个局域网所能传送的最长数据帧中的数据部分</p><p>只有1200位，因此数据报在路由器必须进行分片。试问第二个局域网向其上层要传送多少比特的数据？</p></blockquote><p>IP数据报的总长度-IP数据报的首部=1200-160=1040 bit TCP交给IP的数据3200 bit=1040+1040+1040+80，必须划分<strong>4</strong>个数据报片 4个数据报片的总长度=1200+1200+1200+240=3840 bit</p><blockquote><p>4-22 一个数据报长度为4000字节（固定首部长度）。现在经过一个网络传送，但此网络能够传送的最大数据长度为1500字节。试问应当划分为几个短些的数据报片？各数据报片的数据字段长度、片偏移字段和MF标志为何数值？</p></blockquote><p>数据报总长度减去首部长度，得出IP数据报的数据部分长度=4000-<strong>20</strong>=3980 B 划分一个数据报片的长度=1500-20=1480 B 3980=1480+1480+1020 应当划分3个数据报片</p><table><thead><tr><th>3个数据报片</th><th>数据字段长度</th><th>总长度</th><th>片偏移字段</th><th>MF标志</th></tr></thead><tbody><tr><td>原始数据报</td><td>3980</td><td>4000</td><td><strong>0</strong></td><td>0</td></tr><tr><td>1</td><td>1480</td><td>1500</td><td><strong>0</strong>(0/8)</td><td>1</td></tr><tr><td>2</td><td>1480</td><td>1500</td><td><strong>185</strong>(1480/8)</td><td>1</td></tr><tr><td>3</td><td>1020</td><td>1040</td><td><strong>370</strong>(2*1480/8)</td><td>0</td></tr></tbody></table><blockquote><p>4-41 假定网络中的路由器B的路由表由如下的项目（&quot;目的网络&quot;，&quot;距离&quot;，&quot;下一跳路由器&quot;）</p></blockquote><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281738196.png" alt="image-20220428173813159" tabindex="0" loading="lazy"><figcaption>image-20220428173813159</figcaption></figure><p>现在B收到从C发来的路由信息（&#39;目的网络&#39;，&#39;距离&#39;）</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281738606.png" alt="image-20220428173838572" tabindex="0" loading="lazy"><figcaption>image-20220428173838572</figcaption></figure><p>试求出路由器B更新后的路由表（详细说明步骤）</p><p><strong>修改从C发来的路由表 跳数+1</strong></p><table><thead><tr><th><img src="data:image/png;base64," alt="img" loading="lazy"></th><th>5</th></tr></thead><tbody><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>9</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>5</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>4</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>6</td></tr></tbody></table><p><strong>下一跳改为C</strong></p><table><thead><tr><th><img src="data:image/png;base64," alt="img" loading="lazy"></th><th>7</th><th>C</th><th>无新信息，不更新</th></tr></thead><tbody><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>5</td><td>C</td><td>相同的下一跳，更新</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>9</td><td>C</td><td>新项目，添加</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>5</td><td>C</td><td>不同的下一跳，距离更短，更新</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>4</td><td>E</td><td>不同的下一跳，距离一样，不更新</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>4</td><td>F</td><td>不同的的下一跳，距离更大，不更新</td></tr></tbody></table><blockquote><p>4-42 假定网络中的路由器A的路由表有如下的项目</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281740930.png" alt="image-20220428174014893" tabindex="0" loading="lazy"><figcaption>image-20220428174014893</figcaption></figure><p>现在收到从C发来的路由信息</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281740079.png" alt="image-20220428174029044" tabindex="0" loading="lazy"><figcaption>image-20220428174029044</figcaption></figure><p>试求出路由器A更新后的路由表（详细说明步骤）</p></blockquote><p>跳数加1</p><table><thead><tr><th><img src="data:image/png;base64," alt="img" loading="lazy"></th><th>3</th></tr></thead><tbody><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>2</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>4</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>8</td></tr></tbody></table><p>下一跳改为C</p><table><thead><tr><th><img src="data:image/png;base64," alt="img" loading="lazy"></th><th>3</th><th>C</th><th>不同的下一跳，距离更短，更新</th></tr></thead><tbody><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>2</td><td>C</td><td>相同的下一跳，距离相等，不更新</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>1</td><td>F</td><td>不同的下一跳，距离更大，不更新</td></tr><tr><td><img src="data:image/png;base64," alt="img" loading="lazy"></td><td>5</td><td>G</td><td>不同的下一跳，距离更大，不更新</td></tr></tbody></table><p>分组转发算法（<strong>传统分类IP地址</strong>）【p134】</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281742190.png" alt="image-20220428174226147" tabindex="0" loading="lazy"><figcaption>image-20220428174226147</figcaption></figure><p><strong>划分子网</strong>下的分组转发算法【p140】</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281742546.png" alt="image-20220428174242500" tabindex="0" loading="lazy"><figcaption>image-20220428174242500</figcaption></figure><p>（3）RIP/OSPF【p154，159】</p><p><strong>RIP</strong>协议的特点<strong>： （1）</strong>仅和相邻路由器交换信息</p><p>（2）路由器交换的信息是<strong>当前自己的路由表</strong></p><p>（3）<strong>按固定的时间间隔</strong>交换路由信息</p><p><strong>距离向量算法</strong></p><p>（1）对地址为X的相邻路由器发送过来的RIP报文</p><p>修改&quot;<strong>下一跳</strong>&quot;字段的地址为X</p><p>所有的&quot;<strong>距离</strong>&quot;字段的值加1</p><p>（2）对修改后的RIP报文中的每一个项目</p><p>若原来的路由表中没有目的网络N，则添加到路由表；</p><p>否则，若下一跳路由器地址是X，则替换原来的项目；</p><p>否则，若收到的项目中的距离d小于路由表中的距离，则更新；</p><p>否则什么都不做</p><p><strong>OSPF</strong>协议的基本特点：</p><p>（1)使用洪泛法向本自治系统中<strong>所有路由器</strong>发送信息</p><p>（2）发送的信息是与本路由器<strong>相邻的所有路由器的链路状态</strong></p><p>（3）只有当链路状态<strong>发生变化</strong>时，路由器才向所有路由器用洪泛法发送此信息</p><p><strong>划分子网</strong></p><p>1、网络192.168.40.0是C类网络</p><p>​ 子网划分只能从第4个字节开始</p><p>设子网位为nbit,2^n-2&gt;=6</p><p>n合适的取值为3，即将第4个字节的高3位用于子网位0</p><p>子网掩码是一个32bit的二进制，其中为1的位表示网络位或子网位，为0的位表示主机位</p><p>子网掩码=255.255.255.11100000=255.255.255.224</p><p>2、2^(8-3)-2=30</p><p>每个子网可分配主机30个</p><p>3、第1子网ID=192.168.40.00100000=192.168.40.32</p><p>可分配IP地址范围：</p><p>192.168.40.00100001-192.168.40.00111110</p><p>即192.168.40.33-192.168.40.62</p><p>第2子网ID=192.168.40.01000000=192.168.40.64</p><p>可分配IP地址范围：</p><p>192.168.40.01000001-192.168.40.01011110</p><p>即192.168.40.65-192.168.40.94 ..</p><p>第3子网ID=192.168.40.96</p><p>可分配IP地址范围：192.168.40.97-126</p><p><strong>第5章</strong></p><blockquote><p>5-13 一个UDP用户数据报的数据字段为8192字节。在链路层要使用以太网来传送。试问应当划分为几个IP数据报片？说明每一个IP数据报片的数据字段长度和片偏移字段的值</p></blockquote><p>UDP用户数据报长度=8192+<strong>8</strong>=8200 B</p><p>IP数据报的数据部分=UDP首部+UDP用户数据报的数据部分</p><p>以太网数据字段最大长度为1500 B</p><p>划分的IP数据报的数据部分=1500-20=1480 B</p><p>8200=1480*5+800</p><p>应当划分6个IP数据报片</p><table><thead><tr><th>6个数据报片</th><th>数据字段长度</th><th>总长度</th><th>片偏移字段</th></tr></thead><tbody><tr><td>原始数据报</td><td>8192</td><td>8200</td><td><strong>0</strong></td></tr><tr><td>1</td><td>1480</td><td>1500</td><td><strong>0</strong>(0/8)</td></tr><tr><td>2</td><td>1480</td><td>1500</td><td><strong>185</strong>(1480/8)</td></tr><tr><td>3</td><td>1480</td><td>1500</td><td><strong>370</strong>(2*1480/8)</td></tr><tr><td>4</td><td>1480</td><td>1500</td><td><strong>555</strong>(3*1480/8)</td></tr><tr><td>5</td><td>1480</td><td>1500</td><td><strong>740</strong>(4*1480/8)</td></tr><tr><td>6</td><td>800</td><td>820</td><td><strong>925</strong>(5*1480/8)</td></tr></tbody></table><h2 id="网课习题" tabindex="-1"><a class="header-anchor" href="#网课习题"><span>网课习题</span></a></h2><h3 id="第一章-概述" tabindex="-1"><a class="header-anchor" href="#第一章-概述"><span><strong>第一章--概述</strong></span></a></h3><p>1、在我国第一个实现IPv6的网络是（ ）。A.CHINANet B.EDUNet C.<strong>CERNET2</strong> D.UNINET</p><p>2、因特网起源于（ ）网络。 <strong>&amp;&amp;</strong> 互联网起源于（ ）网络。A.<strong>ARPANET</strong> B.Ethernet C. CATV D.CERNET</p><p>3、人们把（ ）年作为因特网的诞生时间。A.1969 B.<strong>1983</strong> C.1985 D.1993</p><p>4、中国目前最大的ISP是（ ）。A.中国移动B.中国联通 C.<strong>中国电信</strong> D.中国网通</p><p>5、在互联网的标准化中，负责近期工程技术研究的是( ）A.ISO B.IRTF C.<strong>IETF</strong> D.IAB</p><p>6、所有的RFC最终都将成为（ ）A.互联网标准 B.<strong>历史的****RFC</strong> C.建议标准D.ISO标准</p><p>7、中国教育和科研计算机网简称为（ ）A.CHINANET B.EDUNET C.<strong>CERNET</strong> D.UNINET</p><p>8、我国在（ ）年正式接入互联网，并被国际承认。A.1980 B.1989 C.<strong>1994</strong> D.1997</p><p>9、目前负责中国互联网相关管理工作的机构是（ ）。A.工信部 B.<strong>CNNIC</strong> C.CERNET D.邮电部</p><p>10、我国第一个公用分组交换网 CNPAC 在（ ）年建成运行。A.1980 B.<strong>1989</strong> C.1994 D.1997</p><p>11、从网络的作用范围进行分类，网络可以分为PAN、LAN、（ ）、WAN。A.<strong>城域网</strong> B.广域网 C.局域网 D.个人区域网</p><p>12、从作用范围来分，校园网属于（ ）。A.<strong>LAN</strong> B.MAN C.WAN D.PAN</p><p>13、ISO提出的网络体系结构是（ ）。A.<strong>OSI</strong> B.TCP/IP C.SNA D.IEEE</p><p>14、目前互联网上使用的事实上的国际标准是（ ）。A.OSI B.<strong>TCP/IP</strong> C.SNA D.IEEE</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281746157.png" alt="image-20220428174634100" tabindex="0" loading="lazy"><figcaption>image-20220428174634100</figcaption></figure><h3 id="第二章-物理层" tabindex="-1"><a class="header-anchor" href="#第二章-物理层"><span>第二章--物理层</span></a></h3><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281750710.png" alt="image-20220428175007627" tabindex="0" loading="lazy"><figcaption>image-20220428175007627</figcaption></figure><h3 id="第三章-数据链路层" tabindex="-1"><a class="header-anchor" href="#第三章-数据链路层"><span><strong>第三章--数据链路层</strong></span></a></h3><ol><li>PPP帧的标志字段等于0x（ ）A.80 B.<strong>7e</strong> C.ff D.88</li><li>数据链路层封装的PDU称为( )A.分组 B.<strong>帧</strong> C.报文 D.比特流</li><li>数据链路除了物理线路外，还必须有（ ）来控制这些数据的传输。A.软件 B.逻辑链路 C.<strong>通信协议</strong> D.网卡</li><li>数据链路层的帧中封装的数据一般为上一层的（ ）A.<strong>分组</strong> B.帧C.报文D.比特流</li><li>数据链路层协议需要解决的三个基本问题是封装成帧、透明传输与（ ）A.加密技术B.身份验证C.可靠机制 D.<strong>差错控制</strong></li><li>数据链路层中使用最为广泛的检错技术是（ ）A.海明码检验 B.<strong>循环冗余检验</strong> C.奇偶检验 D.公钥加密</li><li>某CRC生成多项式P有n位，则其冗余码应该是（ ）位。A.<strong>n-1</strong> B.n C.n+1 D.32</li><li>PPP帧的标志字段等于0x（ ）。A.80 B.7e C.ff D.88</li><li>在目前的局域网中，（ ）拓扑最为常见。 A.<strong>星形</strong> B.总线C.环形D.网状</li><li>世界上第一个以太网的规约是（ ）。A.<strong>DIX Ethernet V2</strong> B.IEEE 802.3 C.OSI/RM D.TCP/IP</li><li>10BASE-T中的T表示使用的传输媒体是（ ）。A.粗同轴电缆 B.细同轴电缆 C.<strong>双绞线</strong> D.光缆</li><li>10BASE-T中的BASE表示（ ）。A.<strong>基带信号</strong> B.宽带信号C.基本速率D.原始以太网</li><li>理想情况下以太网的极限信道利用率为（ ）。A.a/(1+a) B.<strong>1/(1+a)</strong> C.1/a D.(a+1)/a</li><li>以太网帧格式规定，其数据部分最长为（ ）字节。A.64 B.128C.1000 D.<strong>1500</strong></li><li>使用双绞线组建以太网时，其网线最大长度为（ ）米。A.10 B.50 C.64 D.<strong>100</strong></li><li>当以太网的连接距离超过100米时，在物理层上扩展范围最好的方法是使用（ ）。A.双绞线 B.<strong>光缆</strong> C.同轴电缆 D.无线电</li><li>目前在数据链路层扩展局域网是使用（ ）设备。A.集线器B.转发器C.路由器 D.<strong>交换机</strong></li><li>当以太网出现环路时，可以使用（ ）协议避免广播风暴的出现。A.CSMA/CD B.<strong>STP</strong> C.CRC D.FTTx</li><li>100 BASE-T 以太网的最短帧长为（ ）字节。A.32 B.48 C.<strong>64</strong> D.128</li><li>1000 BASE-T要求使用的双绞线必须是（ ）类线以上。A.3 B.4 C.<strong>5</strong> D.超5</li><li>10 GBASE-T以太网中使用的双绞线必须是（ ）类线以上。A.5 B.5E C.6 D.<strong>6A</strong></li><li><strong>MAC</strong>地址共定义有（<strong>48</strong>）<strong>bit</strong></li><li>用户使用拨号电话线与Modem接入因特网时，一般都是使用（ ）协议。A.ISP B.<strong>PPP</strong> C.PPPOE D.CSMA/CD</li></ol><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281751066.png" alt="image-20220428175157990" tabindex="0" loading="lazy"><figcaption>image-20220428175157990</figcaption></figure><h3 id="第四章-网络层" tabindex="-1"><a class="header-anchor" href="#第四章-网络层"><span><strong>第四章--网络层</strong></span></a></h3><p>1、下列协议属于网际层的是（）A.<strong>ICMP</strong> B.CSMA/CD C.TCP D.HTTP</p><p>2、IP 地址的编址方法有（<strong>3</strong>）种。</p><p>3、IP地址211.85.1.122属于（<strong>C</strong>）类IP地址。</p><p>4、IP地址表示合法的是（）。A.256.123.9.1 B.0.127.1.0 C.<strong>192.168.40.100</strong> D.200.3.6</p><p>5、MAC地址共有（<strong>48</strong> ）bit。</p><p>6、IP 地址是 141.14.72.24，子网掩码是 255.255.192.0，其网络地址为（）A.<strong>141.14.64.0</strong> B.141.14.52.0 C.141.14.32.0 D.141.14.128.0</p><p><strong>IP****地址和子网掩码</strong>都换算成二进制,然后进行与运算(1和1为1，其余都为0)</p><p>7、B类IP地址默认的子网掩码为（ ）A.255.0.0.0 B.<strong>255.255.0.0</strong> C.255.255.255.0 D.255.255.255.255</p><p>8、相对分类的IP地址而言，在划分子网的情况下，路由表项将增加（ ）内容。A.下一跳 B.目的网络地址C.子网掩码D.生存时间</p><p>9、CIDR地址192.168.40.0/22的掩码为（ ）。A.255.255.0.0 B.<strong>255.255.252.0</strong> C.255.255.255.0 D.255.255.255.255</p><p><strong>22</strong>代表<strong>22</strong>位为子网位或者网络位，<strong>32-22=10</strong>位为主机位，11111111.11111111.11111100.00000000(255.255.252.0)</p><p>10、CIDR记法中，10/10表示的掩码为（ ）。A.255.0.0.0 B.<strong>255.192.0.0</strong> C.255.255.0.0 D.255.255.255.0</p><p><strong>11111111.11</strong>000000.0.0(255.192.0.0)</p><p>11.互联网有两大类路由选择协议：IGP与（ ）A.<strong>EGP</strong> B.RIP C.OSPF D.ARP</p><p>12.内部网关协议 IGP有多种，最常见的有OSPF与（ ）A.EGP B.<strong>RIP</strong> C.OSPF D.ARP</p><p>13.外部网关协议中目前使用<strong>最多</strong>的是（ ）A.EGP B.IGRP C.EIGRP <strong>D.BGP-4</strong></p><p>14.内部网关协议 IGP 中最先得到<strong>广泛</strong>使用的协议是（ ）A.EGP <strong>B.RIP</strong> C.OSPF D.ARP</p><p>15.RIP认为不可达网络的距离为（ <strong>16</strong> ）。</p><p>16.整个的路由器结构可划分为两大部分：路由选择部分与（ ）部分。A.<strong>分组转发</strong> B.地址缓存 C.转发表D.路由表</p><p>17.BGP协议中，每一个自治系统中至少要选择一个路由器作为该自治系统的（ ）。A.管理员B.<strong>发言人</strong> C.代理D.缓存结点</p><p>18.路由器是（ ）层设备。A.物理B.数据链路 C.<strong>网络</strong> D.传输</p><p>19.RFC 1918定义的第2个地址块前缀为（ ）位。A.8 B.<strong>12</strong> C.16 D.24</p><p>20.内部主机与外部主机通信时，在NAT路由器上发生了（<strong>2</strong> ）次地址转换。</p><p>21.某主机在发送IP分组时，需要首先使用（）的子网掩码计算目标IP地址对应的网络地址。A.目的主机 B.<strong>本机</strong> C.路由器D.交换机</p><p>22.RIP 允许一条路径最多只能包含 （ <strong>15</strong> ）个路由器。</p><p>23.BGP中，用来与相邻的另一个BGP发言人建立关系的报文是（ ）。A.<strong>打开报文</strong>B.更新报文C.保活报文D.通知报文</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281753105.png" alt="image-20220428175322040" tabindex="0" loading="lazy"><figcaption>image-20220428175322040</figcaption></figure><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281753012.png" alt="image-20220428175333955" tabindex="0" loading="lazy"><figcaption>image-20220428175333955</figcaption></figure><h3 id="第五章-运输层" tabindex="-1"><a class="header-anchor" href="#第五章-运输层"><span>第五章--运输层</span></a></h3><p>1.用户提出服务请求,网络将用户请求传送到服务器;服务器执行用户请求,完成所要求的操作并将结果送回用户,这种工作模式称为（ ）</p><p><strong>A.客户服务器模式</strong></p><p>B.点到点模式</p><p>C.SMA/CD模式</p><p>D.令牌环模式</p><ol start="2"><li>应用层的各种进程通过（ ）实现与运输实体的交互</li></ol><p>A.程序</p><p><strong>B.端口</strong></p><p>C.进程</p><p>D.调用</p><p>3.熟知端口的范围是（ ）</p><p>A.0～99</p><p><strong>B.0～1023</strong></p><p>C.0～255</p><p>D.0～65535</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>4.欲保证一个报文可靠、无差错的传输到接收端，下列哪种说法正确（ ）</p><p><strong>A.TCP最适合</strong></p><p>B.UDP 最适合</p><p>C.两个都可以</p><p>D.不能比较</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>5.下述的哪一种协议是不属于TCP/IP模型的协议（ ）</p><p>A.TCP</p><p>B.UDP</p><p>C.ICMP</p><p><strong>D.HDLC</strong></p><ol start="6"><li>UDP 协议校验的数据是（ ）</li></ol><p>A.首部＋伪首部</p><p>B.首部</p><p><strong>C.首部＋数据</strong></p><p>D.伪首部＋数据</p><ol start="7"><li>UDP中伪首部中的IP地址内容和编排顺序是（ ）</li></ol><p>A.只有源IP地址</p><p>B.只有目的IP地址</p><p><strong>C.源IP地址＋目的IP地址</strong></p><p>D.目的IP地址+源IP地址</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>8.TCP 的主要功能是（ ）</p><p>A.进行数据分组</p><p><strong>B.保证可靠传输</strong></p><p>C.确定数据传输路径</p><p>D.提高传输速度</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>9.TCP报文中确认序号指的是 （ ）</p><p>A.已经收到的最后一个数据序号</p><p><strong>B.期望收到的第一个字节序号</strong></p><p>C.出现错误的数据序号</p><p>D.请求重传的数据序号</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>10.（ ）的功能不属于TCP协议的职责</p><p>A.端到端的流量控制</p><p>B.重传出错或被丢弃的数据</p><p>C.识别接收次序与发送次序不同的数据</p><p><strong>D.发现网络错误时候报告网络错误</strong></p><p>11.在TCP/IP参考模型中,运输层的主要作用是在互联网络的源主机和目的主机对等实体之间建立用于会话的（ ）。</p><p>A.物理连接</p><p>B.操作连接</p><p><strong>C.端到端连接</strong></p><p>D.控制连接</p><p>12.下列不属于通信子网的是（ ）</p><p>A.物理层</p><p>B.数据链路层</p><p>C.网络层</p><p><strong>D.运输层</strong></p><p>13.可靠的传输协议中的“可靠”指的是（ ）</p><p>A.使用面向连接的会话</p><p>B.使用“尽力而为”的传输</p><p>C.用滑动窗口来维持可靠性</p><p><strong>D.使用确认机制来确保传输的数据不丢失</strong></p><p>14.在 TCP/IP 参考模型中TCP协议工作在：（ ）</p><p>A.应用层</p><p><strong>B.运输层</strong></p><p>C.互连层</p><p>D.主机-网络层</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>15.TCP报文段中<strong>序号字段</strong>指的是（ ）</p><p><strong>A.数据部分第一个字节</strong></p><p>B.数据部分最后一个字节</p><p>C.报文首部第一个字节</p><p>D.报文最后一个字节</p><p>16.TCP报文中<strong>确认序号</strong>指的是（ ）</p><p>A.已经收到的最后一个数据序号</p><p><strong>B.期望收到的第一个字节序号</strong></p><p>C.出现错误的数据序号</p><p>D.请求重传的数据序号</p><p>17.TCP报文的首部最小长度是（ 20 ）字节。</p><p>18.TCP的确认是对接收到的数据中（ ） 表示确认</p><p><strong>A.最高序号</strong></p><p>B.第一个序号</p><p>C.第二个序号</p><p>D.倒数第二个序号</p><p>19.TCP协议是采用（ ）进行编号的</p><p>A.按报文段</p><p><strong>B.字节</strong></p><p>C.数据帧</p><p>D.IP数据报</p><p>满分：4.00 分</p><p>得分：4.00 分</p><p>20.TCP采用（ ）的方式进行流量控制</p><p><strong>A.可变发送窗口</strong></p><p>B.固定发送窗口</p><p>C.固定接收窗口</p><p>D.以上都不是</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281756617.png" alt="image-20220428175608565" tabindex="0" loading="lazy"><figcaption>image-20220428175608565</figcaption></figure><h3 id="第六章-应用层" tabindex="-1"><a class="header-anchor" href="#第六章-应用层"><span><strong>第六章--应用层</strong></span></a></h3><p>1.在互联网上共有（ <strong>13</strong> ）个不同的根域名服务器</p><p>2.FTP进行控制连接时使用的默认端口号为( <strong>21</strong> )</p><p>3.FTP进行数据连接时使用的默认端口号为（<strong>20</strong>）</p><p>4.使用（ <strong>URL</strong> ）来标志万维网上的各种文档</p><p>5.（ <strong>URL</strong> ）是互联网资源的位置表示形式</p><p>6.目前互联网中使用最多的URL协议是（<strong>HTTP</strong>）</p><p>7.万维网站点使用（ <strong>Cookie</strong> ）来跟踪用户</p><p>8.通过（ <strong>DHCP</strong> ）协议可以在网络中动态地获得IP地址</p><p>9.有关网络域名系统的描述中，不正确的是（ ）</p><p>A.网络域名系统的缩写为DNS</p><p>B.每个域名可以由几个域组成，域与域之间用&quot;.&quot;分开</p><p>C.<strong>域名中的最左端的域称为顶级域</strong></p><p>D.cn是常用的顶级域名代码</p><p>10.系统对WWW 网页存储的默认格式是( HTML )</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202204281756953.png" alt="image-20220428175635895" tabindex="0" loading="lazy"><figcaption>image-20220428175635895</figcaption></figure>`,339)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};